ruleSearch.bookUrl:
@js:
let a=java.getString('class.pic@html')
//java.log(JSON.stringify(a))
let b=String(a).match(/upclick\(\'(.*?)\'/)[1]
//java.log(b)


let src=java.get("src")

if(src.match(/番茄小说/)){
 let urls ="https://www.fanqxsw.com/book/"
 java.log(urls) 
 let url =`${urls}${b}`+".html"
url
} else if(src.match(/可乐小说/)){
 let urls ="https://www.kelexs.com/book/"
 java.log(urls)
 let url =`${urls}${b}`+".html"
url
} else if(src.match(/找书吧/)){
 let urls ="https://www.zhaoshuba.com/book/"
 java.log(urls)
 let url =`${urls}${b}`+".html"
url
}

