@js:
let href=baseUrl.match(/chapter\/(.*)\.html/)
let u=href[1]
//java.log(JSON.stringify(u))

let page=src.match(/value\="(.*?)"/g)
//java.log(JSON.stringify(page))

let nums=[];
page.forEach(function(number){
  let match=number.match(/\d+/);
  if(match){
    nums.push(parseInt(match[0],10));
  }
})

let max=nums.slice(-1)
//java.log(JSON.stringify(max))

let mc=baseUrl.match(/http[\S\s]*?com/)
java.log(JSON.stringify(mc))

